import { Resource } from "../resource/Resource";
import { Texture } from "../resource/Texture";

export type MSDFFontBounds = readonly [number, number, number, number];

export interface MSDFFontMetrics {
    readonly emSize: number;
    readonly lineHeight: number;
    readonly ascender: number;
    readonly descender: number;
}

export interface MSDFFontParameters {
    readonly distanceRange: number;
    readonly scale: number;
}

export interface MSDFFontGlyph {
    readonly unicode: number;
    readonly advance: number;
    readonly planeBounds: MSDFFontBounds;
    readonly atlasBounds: MSDFFontBounds;
    readonly uv: MSDFFontBounds;
    readonly empty: boolean;
}

export interface MSDFFontKerning {
    readonly left: number;
    readonly right: number;
    readonly advance: number;
}

interface MSDFFontDocument {
    version: number;
    atlas: {
        url: string;
        width: number;
        height: number;
        yOrigin: "top" | "bottom";
    };
    metrics: MSDFFontMetrics;
    msdf: MSDFFontParameters;
    glyphCount: number;
    glyphs: Array<{
        unicode: number;
        advance: number;
        planeBounds: MSDFFontBounds;
        atlasBounds: MSDFFontBounds;
        uv: MSDFFontBounds;
        empty: boolean;
    }>;
    kerning: MSDFFontKerning[];
}

/**
 * @en A validated MSDF font resource. This class only owns the font metadata and its atlas dependency.
 * @zh 经过校验的 MSDF 字体资源。本类只负责字体元数据及其 atlas 依赖，不负责渲染。
 */
export class MSDFFont extends Resource {
    /** Current MSDF resource contract version. */
    static readonly VERSION = 1;

    private _atlas: Texture;
    private _metrics: MSDFFontMetrics;
    private _msdf: MSDFFontParameters;
    private _glyphs: Map<number, MSDFFontGlyph>;
    private _kerning: Map<string, MSDFFontKerning>;

    /** The URL recorded by the resource document. */
    readonly atlasURL: string;
    /** The atlas width declared by the resource document. */
    readonly atlasWidth: number;
    /** The atlas height declared by the resource document. */
    readonly atlasHeight: number;
    /** The atlas coordinate origin declared by the resource document. */
    readonly yOrigin: "top" | "bottom";

    private constructor(document: MSDFFontDocument, atlas: Texture) {
        super();
        this._atlas = atlas;
        this.addDep(atlas);
        this.atlasURL = document.atlas.url;
        this.atlasWidth = document.atlas.width;
        this.atlasHeight = document.atlas.height;
        this.yOrigin = document.atlas.yOrigin;
        this._metrics = Object.freeze(document.metrics);
        this._msdf = Object.freeze(document.msdf);
        this._glyphs = new Map();
        for (const glyph of document.glyphs)
            this._glyphs.set(glyph.unicode, Object.freeze(glyph));
        this._kerning = new Map();
        for (const pair of document.kerning)
            this._kerning.set(MSDFFont.kerningKey(pair.left, pair.right), Object.freeze(pair));
    }

    /** The loaded MSDF atlas texture. */
    get atlas(): Texture {
        return this._atlas;
    }

    /** Font metrics used by layout. */
    get metrics(): Readonly<MSDFFontMetrics> {
        return this._metrics;
    }

    /** Distance-field parameters consumed by the renderer. */
    get msdf(): Readonly<MSDFFontParameters> {
        return this._msdf;
    }

    /** Validated glyph records indexed by Unicode codepoint. */
    get glyphs(): ReadonlyMap<number, MSDFFontGlyph> {
        return this._glyphs;
    }

    /** Validated kerning records indexed by a left/right codepoint pair. */
    get kerning(): ReadonlyMap<string, MSDFFontKerning> {
        return this._kerning;
    }

    /**
     * Return the declared atlas URL after validating the document envelope.
     * This lets a loader reject an invalid dependency declaration before downloading it.
     */
    static getAtlasURL(data: unknown, sourceURL: string = ""): string {
        const document = MSDFFont.readDocumentEnvelope(data, sourceURL);
        return document.atlas.url;
    }

    /** Parse and validate a document against a loaded atlas texture. */
    static parse(data: unknown, atlas: Texture, sourceURL: string = ""): MSDFFont {
        const document = MSDFFont.readDocument(data, sourceURL);
        if (!(atlas instanceof Texture))
            MSDFFont.fail(sourceURL, "atlas loader returned a non-Texture resource");
        if (atlas.destroyed)
            MSDFFont.fail(sourceURL, "atlas texture is destroyed");
        if (atlas.width !== document.atlas.width || atlas.height !== document.atlas.height)
            MSDFFont.fail(sourceURL, `atlas texture size ${atlas.width}x${atlas.height} does not match declared ${document.atlas.width}x${document.atlas.height}`);

        return new MSDFFont(document, atlas);
    }

    getGlyph(unicode: number): MSDFFontGlyph | null {
        return this._glyphs.get(unicode) || null;
    }

    getKerning(left: number, right: number): number {
        return this._kerning.get(MSDFFont.kerningKey(left, right))?.advance || 0;
    }

    protected _disposeResource(): void {
        this._atlas = null;
        this._metrics = null;
        this._msdf = null;
        this._glyphs?.clear();
        this._kerning?.clear();
    }

    private static readDocumentEnvelope(data: unknown, sourceURL: string): { atlas: MSDFFontDocument["atlas"] } {
        const root = MSDFFont.record(data, sourceURL, "document");
        if (root.version !== MSDFFont.VERSION)
            MSDFFont.fail(sourceURL, `unsupported version '${root.version}'`);
        const atlas = MSDFFont.record(root.atlas, sourceURL, "atlas");
        if (typeof atlas.url !== "string" || atlas.url.length === 0)
            MSDFFont.fail(sourceURL, "atlas.url must be a non-empty string");
        return { atlas: atlas as MSDFFontDocument["atlas"] };
    }

    private static readDocument(data: unknown, sourceURL: string): MSDFFontDocument {
        const root = MSDFFont.record(data, sourceURL, "document");
        if (root.version !== MSDFFont.VERSION)
            MSDFFont.fail(sourceURL, `unsupported version '${root.version}'`);

        const atlasValue = MSDFFont.record(root.atlas, sourceURL, "atlas");
        const atlasURL = atlasValue.url;
        if (typeof atlasURL !== "string" || atlasURL.length === 0)
            MSDFFont.fail(sourceURL, "atlas.url must be a non-empty string");
        const width = MSDFFont.positiveInteger(atlasValue.width, sourceURL, "atlas.width");
        const height = MSDFFont.positiveInteger(atlasValue.height, sourceURL, "atlas.height");
        if (atlasValue.yOrigin !== "top" && atlasValue.yOrigin !== "bottom")
            MSDFFont.fail(sourceURL, "atlas.yOrigin must be 'top' or 'bottom'");

        const metricsValue = MSDFFont.record(root.metrics, sourceURL, "metrics");
        const metrics: MSDFFontMetrics = Object.freeze({
            emSize: MSDFFont.positiveNumber(metricsValue.emSize, sourceURL, "metrics.emSize"),
            lineHeight: MSDFFont.positiveNumber(metricsValue.lineHeight, sourceURL, "metrics.lineHeight"),
            ascender: MSDFFont.finiteNumber(metricsValue.ascender, sourceURL, "metrics.ascender"),
            descender: MSDFFont.finiteNumber(metricsValue.descender, sourceURL, "metrics.descender"),
        });

        const msdfValue = MSDFFont.record(root.msdf, sourceURL, "msdf");
        const msdf: MSDFFontParameters = Object.freeze({
            distanceRange: MSDFFont.positiveNumber(msdfValue.distanceRange, sourceURL, "msdf.distanceRange"),
            scale: MSDFFont.positiveNumber(msdfValue.scale, sourceURL, "msdf.scale"),
        });

        const glyphValues = root.glyphs;
        if (!Array.isArray(glyphValues) || glyphValues.length === 0)
            MSDFFont.fail(sourceURL, "glyphs must be a non-empty array");
        const glyphCount = MSDFFont.positiveInteger(root.glyphCount, sourceURL, "glyphCount");
        if (glyphCount !== glyphValues.length)
            MSDFFont.fail(sourceURL, `glyphCount ${glyphCount} does not match glyphs.length ${glyphValues.length}`);

        const glyphs: MSDFFontDocument["glyphs"] = [];
        const unicodeSet = new Set<number>();
        for (let i = 0; i < glyphValues.length; i++) {
            const value = MSDFFont.record(glyphValues[i], sourceURL, `glyphs[${i}]`);
            const unicode = MSDFFont.integerInRange(value.unicode, 0, 0x10ffff, sourceURL, `glyphs[${i}].unicode`);
            if (!unicodeSet.add(unicode))
                MSDFFont.fail(sourceURL, `duplicate glyph unicode ${unicode}`);
            const advance = MSDFFont.finiteNumber(value.advance, sourceURL, `glyphs[${i}].advance`);
            const planeBounds = MSDFFont.bounds(value.planeBounds, sourceURL, `glyphs[${i}].planeBounds`);
            const atlasBounds = MSDFFont.bounds(value.atlasBounds, sourceURL, `glyphs[${i}].atlasBounds`);
            const empty = value.empty === true;
            const planeEmpty = planeBounds[0] === planeBounds[2] && planeBounds[1] === planeBounds[3];
            const atlasEmpty = atlasBounds[0] === atlasBounds[2] && atlasBounds[1] === atlasBounds[3];
            if (empty) {
                if (!planeEmpty || !atlasEmpty || planeBounds.some(value => value !== 0) || atlasBounds.some(value => value !== 0))
                    MSDFFont.fail(sourceURL, `glyphs[${i}].empty requires zero planeBounds and atlasBounds`);
            }
            else {
                if (planeEmpty || atlasEmpty || planeBounds[2] <= planeBounds[0] || planeBounds[3] <= planeBounds[1])
                    MSDFFont.fail(sourceURL, `glyphs[${i}] has empty or inverted bounds; set empty:true for a whitespace glyph`);
                if (atlasBounds[0] < 0 || atlasBounds[1] < 0 || atlasBounds[2] > width || atlasBounds[3] > height)
                    MSDFFont.fail(sourceURL, `glyphs[${i}].atlasBounds exceed the declared atlas dimensions`);
            }
            const uv: MSDFFontBounds = Object.freeze([
                atlasBounds[0] / width,
                atlasBounds[1] / height,
                atlasBounds[2] / width,
                atlasBounds[3] / height,
            ]);
            glyphs.push(Object.freeze({ unicode, advance, planeBounds, atlasBounds, uv, empty }));
        }

        const kerningValues = root.kerning == null ? [] : root.kerning;
        if (!Array.isArray(kerningValues))
            MSDFFont.fail(sourceURL, "kerning must be an array when present");
        const kerning: MSDFFontKerning[] = [];
        const kerningSet = new Set<string>();
        for (let i = 0; i < kerningValues.length; i++) {
            const value = MSDFFont.record(kerningValues[i], sourceURL, `kerning[${i}]`);
            const left = MSDFFont.integerInRange(value.left, 0, 0x10ffff, sourceURL, `kerning[${i}].left`);
            const right = MSDFFont.integerInRange(value.right, 0, 0x10ffff, sourceURL, `kerning[${i}].right`);
            if (!unicodeSet.has(left) || !unicodeSet.has(right))
                MSDFFont.fail(sourceURL, `kerning[${i}] references a missing glyph`);
            const key = MSDFFont.kerningKey(left, right);
            if (!kerningSet.add(key))
                MSDFFont.fail(sourceURL, `duplicate kerning pair ${key}`);
            kerning.push(Object.freeze({ left, right, advance: MSDFFont.finiteNumber(value.advance, sourceURL, `kerning[${i}].advance`) }));
        }

        return {
            version: MSDFFont.VERSION,
            atlas: { url: atlasURL, width, height, yOrigin: atlasValue.yOrigin },
            metrics,
            msdf,
            glyphCount,
            glyphs,
            kerning,
        };
    }

    private static record(value: unknown, sourceURL: string, name: string): Record<string, any> {
        if (value == null || typeof value !== "object" || Array.isArray(value))
            MSDFFont.fail(sourceURL, `${name} must be an object`);
        return value as Record<string, any>;
    }

    private static bounds(value: unknown, sourceURL: string, name: string): MSDFFontBounds {
        if (!Array.isArray(value) || value.length !== 4)
            MSDFFont.fail(sourceURL, `${name} must contain four numbers`);
        return Object.freeze(value.map((item, index) => MSDFFont.finiteNumber(item, sourceURL, `${name}[${index}]`))) as MSDFFontBounds;
    }

    private static finiteNumber(value: unknown, sourceURL: string, name: string): number {
        if (typeof value !== "number" || !Number.isFinite(value))
            MSDFFont.fail(sourceURL, `${name} must be a finite number`);
        return value;
    }

    private static positiveNumber(value: unknown, sourceURL: string, name: string): number {
        const result = MSDFFont.finiteNumber(value, sourceURL, name);
        if (result <= 0)
            MSDFFont.fail(sourceURL, `${name} must be greater than zero`);
        return result;
    }

    private static positiveInteger(value: unknown, sourceURL: string, name: string): number {
        const result = MSDFFont.finiteNumber(value, sourceURL, name);
        if (!Number.isInteger(result) || result <= 0)
            MSDFFont.fail(sourceURL, `${name} must be a positive integer`);
        return result;
    }

    private static integerInRange(value: unknown, min: number, max: number, sourceURL: string, name: string): number {
        const result = MSDFFont.finiteNumber(value, sourceURL, name);
        if (!Number.isInteger(result) || result < min || result > max)
            MSDFFont.fail(sourceURL, `${name} must be an integer from ${min} to ${max}`);
        return result;
    }

    private static kerningKey(left: number, right: number): string {
        return `${left}:${right}`;
    }

    private static fail(sourceURL: string, message: string): never {
        const suffix = sourceURL ? ` in '${sourceURL}'` : "";
        throw new Error(`Invalid MSDF font${suffix}: ${message}`);
    }
}
