import { AnimationWrapMode } from "../components/FrameAnimation";
import { Resource } from "./Resource";
import { Texture } from "./Texture";


export interface IAtlasAnimationInfo {
    /**
     * @en The interval between frame changes, in milliseconds.
     * @zh 帧改变之间的间隔时间，单位为毫秒。
     */
    interval: number;

    /**
     * @en The delay between each repeat, in milliseconds.
     * @zh 每次重复之间的延迟，单位为毫秒。
     */
    repeatDelay: number;

    /**
     * @en Playback order type.
     * @zh 播放顺序类型。
     */
    wrapMode: AnimationWrapMode;

    /**
     * @en Extra transition delays, in milliseconds, indexed in the full frame list. Forward playback uses the current absolute index; reverse playback uses the preceding index.
     * @zh 按完整帧列表索引配置的额外切换延迟，单位为毫秒。正序使用当前绝对索引，倒序使用前一绝对索引。
     */
    frameDelays: Array<number>;

    /**
     * @en Whether to repeat frameDelays using its array length as the period. Default is false. Absolute delay indices are used regardless of the playback range.
     * @zh 是否以 frameDelays 数组长度为周期循环匹配延迟，默认为 false。使用绝对延迟索引，不随播放范围改变匹配起点。
     */
    frameDelaysLoop?: boolean;
}


/**
 * @en Resource class for managing an atlas, which is a collection of textures and their frames.
 * @zh 管理大图合集资源的类，该类包含纹理和它们的帧。
 */
export class AtlasResource extends Resource {
    private readonly _boundTextures: Set<Texture> = new Set();

    /**
     * @en The directory where the atlas resource is stored.
     * @zh 存储大图合集资源的目录。
     */
    dir: string;
    /**
     * @en An array of textures contained within the atlas.
     * @zh 包含在大图合集中的纹理数组。
     */
    readonly textures: Array<Texture>;
    /**
     * @en An array of texture frames, which are individual images within the atlas.
     * @zh 大图合集中的纹理帧数组，它们是大图中的单个图像。
     */
    readonly frames: Array<Texture>;
    /**
     * @en The animation information of the atlas.
     * @zh 大图合集的动画信息。
     */
    animation: IAtlasAnimationInfo;

    /**
     * @en User-defined data associated with the atlas resource.
     * @zh 与大图合集资源相关联的用户自定义数据。
     */
    userData: any;

    /**
     * @en Creates a new instance of the AtlasResource class.
     * @param dir Directory of the atlas.
     * @param textures Array of textures in the atlas.
     * @param frames Array of frames corresponding to the textures.
     * @zh 创建AtlasResource类的新实例。实例化大图合集资源。
     * @param dir 大图合集的目录路径。
     * @param textures 大图合集中的纹理数组。
     * @param frames 对应纹理的帧数组。
     */
    constructor(dir: string, textures: Array<Texture>, frames: Array<Texture>) {
        super();

        this.dir = dir;
        this.textures = textures;
        this.frames = frames;
        this._bindTextures();
    }

    /**
     * @en Updates the atlas resource with new textures and frames.
     * @param textures Array of textures to add to the atlas.
     * @param frames Array of frames corresponding to the textures.
     * @zh 使用新的纹理和帧更新大图合集资源。
     * @param textures 要添加到大图合集的纹理数组。
     * @param frames 对应纹理的帧数组。 
     */
    update(textures: Array<Texture>, frames: Array<Texture>) {
        const nextTextures = textures.slice();
        const nextFrames = frames.slice();
        for (const tex of new Set([...nextFrames, ...nextTextures])) {
            if (tex.destroyed)
                throw new Error("cannot bind a destroyed texture to an atlas");
            if (tex._atlas && tex._atlas !== this)
                throw new Error("texture is already bound to another atlas");
        }

        this._disposeResource();

        this.textures.push(...nextTextures);
        this.frames.push(...nextFrames);
        this._bindTextures();
    }

    private _bindTextures(): void {
        const textures = new Set([...this.frames, ...this.textures]);
        for (const tex of textures) {
            if (tex.destroyed)
                throw new Error("cannot bind a destroyed texture to an atlas");
            if (tex._atlas)
                throw new Error("texture is already bound to another atlas");
        }

        for (const tex of textures) {
            const referenceCount = tex.referenceCount;
            this._addReference(referenceCount);
            tex._addReference();
            tex._atlas = this;
            this._boundTextures.add(tex);
        }
    }

    /**
     * @en Disposes of the resources used by the atlas, destroying all textures and frames.
     * @zh 释放大图合集使用的资源，销毁所有纹理和帧。
     */
    protected _disposeResource(): void {
        let propagatedReferences = 0;
        const references = new Map<Texture, number>();
        for (const tex of this._boundTextures) {
            if (tex._atlas !== this)
                throw new Error("atlas texture binding is inconsistent");
            if (tex.referenceCount < 1)
                throw new Error("atlas texture owner reference is missing");

            const count = tex.referenceCount - 1;
            references.set(tex, count);
            propagatedReferences += count;
        }
        if (propagatedReferences > this.referenceCount)
            throw new Error("atlas texture references exceed the atlas reference count");

        for (const tex of this._boundTextures) {
            tex._atlas = null;
            tex._removeReference();
            this._removeReference(references.get(tex)!);
        }
        this._boundTextures.clear();

        this.frames.length = 0;
        this.textures.length = 0;
    }
}
