import { MSDFFont } from "../display/MSDFFont";
import { IResourceLoader, ILoadTask, Loader } from "../net/Loader";
import { URL } from "../net/URL";

class MSDFFontLoader implements IResourceLoader {
    async load(task: ILoadTask): Promise<MSDFFont> {
        const data = await task.loader.fetch(task.url, "json", task.progress.createCallback(0.2), task.options);
        if (!data)
            return null;

        const atlasURL = URL.formatURL(URL.join(URL.getPath(task.url), MSDFFont.getAtlasURL(data, task.url)));
        const atlas = await task.loader.load(atlasURL, {
            type: Loader.IMAGE,
            initiator: task,
        }, task.progress.createCallback(0.8));
        if (!atlas)
            return null;

        return MSDFFont.parse(data, atlas, task.url);
    }
}

Loader.registerLoader(["msdf"], MSDFFontLoader, Loader.MSDF);
