import { Config } from "../../Config";
import { ILaya } from "../../ILaya";
import { LayaEnv } from "../../LayaEnv";
import { NodeFlags } from "../Const";
import { DrawTextureCmd } from "../display/cmd/DrawTextureCmd";
import { IGraphicsCmd } from "../display/IGraphics";
import { Sprite } from "../display/Sprite";
import { Event } from "../events/Event";
import { SerializeUtil } from "../loaders/SerializeUtil";
import { Color } from "../maths/Color";
import { Point } from "../maths/Point";
import { Loader } from "../net/Loader";
import { AtlasResource } from "../resource/AtlasResource";
import { Texture } from "../resource/Texture";
import { Component } from "./Component";

export enum AnimationWrapMode {
    /**
     * @en Animation playback order type: Forward playback.
     * @zh 动画播放顺序类型：正序播放。
     */
    Positive,
    /**
     * @en Animation playback order type: Reverse playback.
     * @zh 动画播放顺序类型：倒序播放。
     */
    Reverse,
    /**
     * @en Animation playback order type: Ping-pong playback (changes playback direction after reaching the end when continuing to play).
     * @zh 动画播放顺序类型：pingpong播放(当按指定顺序播放完结尾后，如果继续播放，则会改变播放顺序)。
     */
    PingPong,
}

export enum AnimationStretchMode {
    /**
     * @en No stretch.
     * @zh 不拉伸。
     */
    None,

    /**
     * @en Fill the entire sprite size.
     * @zh 填满整个精灵尺寸。
     */
    Fill,

    /**
     * @en Resize the sprite to fit the size of the first frame.
     * @zh 调整精灵尺寸适应第一帧的大小。
     */
    ResizeToFit
}

/**
 * @en The FrameAnimation component is used to play frame animation.
 * @zh FrameAnimation 组件，用于播放帧动画。
 */
export class FrameAnimation extends Component {
    /**
     * @en The interval between frame changes, in milliseconds.
     * @zh 帧改变之间的间隔时间，单位为毫秒。
     */
    interval: number;

    /**
     * @en The delay between each repeat, in milliseconds.
     * @zh 每次重复之间的延迟，单位为毫秒。
     */
    repeatDelay: number = 0;

    /**
     * @en Whether to repeat frameDelays using its array length as the period. Default is false. Matching uses absolute delay indices and does not restart at rangeStart.
     * @zh 是否以 frameDelays 数组长度为周期循环匹配延迟，默认为 false。按绝对延迟索引匹配，不会在 rangeStart 处重新对齐。
     */
    frameDelaysLoop: boolean = false;

    /**
     * @en Playback speed.
     * @zh 播放速率。
     */
    timeScale: number = 1;

    private _wrapMode: AnimationWrapMode = 0;
    private _loop: boolean = true;
    private _frame: number = 0;
    private _frames: Texture[];
    private _delays: number[];
    private _autoPlay: boolean = true;
    private _stretchMode: AnimationStretchMode = 0;
    private _offset: Point;
    private _source: string = "";
    private _images: string[];
    private _color: Color;

    private _atlas: AtlasResource;
    private _playing: boolean = false;
    private _activeStart: number = 0;
    private _count: number = 0;
    private _rangeStart: number = 0;
    private _rangeEnd: number = -1;
    private _index: number = 0;
    private _elapsed: number = 0;
    private _reversed: boolean;
    private _drawCmd: DrawTextureCmd;
    private _drawCmds: DrawTextureCmd[];
    private _loadId: number = 0;
    private _changingSize: boolean;

    /** @internal */
    _labels: string[];

    declare readonly owner: Sprite;

    /**
     * @en Constructor method of Animation.
     * @zh 动画类的构造方法
     */
    constructor() {
        super();

        this.interval = Config.animationInterval;
        this._frames = [];
        this._drawCmds = [];
        this._delays = [];
        this._offset = new Point();
        this._color = new Color(1, 1, 1, 1);
        this._singleton = false;
        this.runInEditor = true;
    }

    /**
     * @en The index of the current frame within the active playback range.
     * @zh 当前有效播放区间内的帧索引。
     */
    get frame(): number {
        return LayaEnv.isPlaying ? this._frame : this._index;
    }

    set frame(value: number) {
        value = Math.floor(value);
        if (!Number.isFinite(value))
            value = 0;
        if (this._count > 0)
            value = Math.max(0, Math.min(value, this._count - 1));
        this._index = this._frame = value;
        this.drawFrame();
        if (this._labels?.[value])
            this.owner.event(Event.LABEL, this._labels[value]);
    }

    /**
     * @en The inclusive start index in the full frame list. Default is 0. Changing the range resets the frame and elapsed time without changing the playing state.
     * @zh 完整帧列表中的开始帧索引，包含此帧，默认为 0。修改范围会重置当前帧和累计时间，但不改变播放状态。
     */
    get rangeStart(): number {
        return this._rangeStart;
    }

    set rangeStart(value: number) {
        value = Number.isFinite(value) ? Math.max(0, Math.floor(value)) : 0;
        if (this._rangeStart === value)
            return;

        this._rangeStart = value;
        this.updateActiveRange(true);
    }

    /**
     * @en The inclusive end index in the full frame list. Default is -1, meaning the last frame. Bounds are clamped when frames are available; an end before the start resolves to a single frame at the start. The configured values are retained for later resource loads.
     * @zh 完整帧列表中的结束帧索引，包含此帧。默认为 -1，表示最后一帧。资源就绪后会限制实际播放边界；结束帧小于开始帧时只播放开始帧。配置值会保留，供后续加载资源时使用。
     */
    get rangeEnd(): number {
        return this._rangeEnd;
    }

    set rangeEnd(value: number) {
        value = Number.isFinite(value) ? Math.max(-1, Math.floor(value)) : -1;
        if (this._rangeEnd === value)
            return;

        this._rangeEnd = value;
        this.updateActiveRange(true);
    }

    /**
     * @en The number of frames in the active playback range.
     * @zh 当前有效播放区间的帧数。
     */
    get count(): number {
        return this._count;
    }

    /**
     * @en The current animation frame image array.
     * @zh 当前动画的帧图像数组。
     */
    get frames(): ReadonlyArray<Texture> {
        return this._frames;
    }

    set frames(value: ReadonlyArray<Texture>) {
        if (this._drawCmd) {
            this.owner._graphics?.removeCmd(this._drawCmd);
            this._drawCmd = null;
        }
        for (let cmd of this._drawCmds) {
            (cmd as IGraphicsCmd).lock = false;
            cmd.recover();
        }
        this._drawCmds.length = 0;
        this._frames.length = 0;
        this.owner._graphics?.preRegisterFrameAnimationCmds(null);

        if (value != null && value.length > 0) {
            this._frames.push(...value);

            let dx = 0, dy = 0;
            if (this._stretchMode === AnimationStretchMode.None) {
                dx = this._offset.x;
                dy = this._offset.y;
            }

            let stretch = this._stretchMode === AnimationStretchMode.Fill;
            for (let tex of value) {
                let cmd = stretch ? DrawTextureCmd.create(tex, 0, 0, 1, 1, null, 1, null, null, null, true)
                    : DrawTextureCmd.create(tex, dx, dy);
                (cmd as IGraphicsCmd).lock = true;
                this._drawCmds.push(cmd);
            }

            this.updateActiveRange(false);
            this._elapsed = 0;
            if (this._wrapMode === AnimationWrapMode.Reverse)
                this._frame = this._count - 1;
            else {
                this._reversed = false;
                this._frame = (this._index > 0 && this._index < this._count) ? this._index : 0;
            }

            this.updateSizeToFit();

            this.drawFrame();
            this.owner.graphics.preRegisterFrameAnimationCmds(this._drawCmds);
        }
        else {
            this._activeStart = 0;
            this._count = 0;
        }
    }

    /**
     * @en Extra transition delays, in milliseconds, indexed in the full frame list. Forward playback uses the current absolute index; reverse playback uses the preceding index. frameDelaysLoop optionally repeats this array.
     * @zh 按完整帧列表索引配置的额外切换延迟，单位为毫秒。正序使用当前绝对索引，倒序使用前一绝对索引。可通过 frameDelaysLoop 循环复用此数组。
     */
    get frameDelays(): Array<number> {
        return this._delays;
    }

    /**
     * @en Whether the animation is playing.
     * @zh 动画是否正在播放。
     */
    get isPlaying(): boolean {
        return this._playing;
    }

    /**
     * @en Whether to automatically play the animation after the component is activated.
     * @zh 是否在组件激活后自动播放动画。
     */
    get autoPlay(): boolean {
        return this._autoPlay;
    }

    set autoPlay(value: boolean) {
        this._autoPlay = value;
        if (this.enabled) {
            if (value)
                this.play();
            else
                this.stop();
        }
    }

    /**
     * @en Playback order type.
     * @zh 播放顺序类型。
     */
    get wrapMode(): AnimationWrapMode {
        return this._wrapMode;
    }

    set wrapMode(value: AnimationWrapMode) {
        if (this._wrapMode != value) {
            this._wrapMode = value;
            if (this._playing) {
                if (value === AnimationWrapMode.Reverse)
                    this._reversed = true;
                else if (value === AnimationWrapMode.Positive)
                    this._reversed = false;
            }
        }
    }

    /**
     * @en Whether to loop playback. The default is true.
     * @zh 是否循环播放。默认为 true。
     */
    get loop(): boolean {
        return this._loop;
    }

    set loop(value: boolean) {
        if (this._loop != value) {
            this._loop = value;
            if (value && !this._playing && this._autoPlay)
                this.play();
        }
    }

    /**
     * @en The stretch mode of the animation. The default is AnimationStretchMode.None.
     * @zh 动画的拉伸模式。默认为 AnimationStretchMode.None。
     */
    get stretchMode(): AnimationStretchMode {
        return this._stretchMode;
    }

    set stretchMode(value: AnimationStretchMode) {
        if (this._changingSize)
            return;

        if (this._stretchMode != value) {
            this._stretchMode = value;

            if (this._count > 0) {
                if (this._stretchMode === AnimationStretchMode.ResizeToFit) {
                    let w = this.width, h = this.height;
                    if (w > 0 && h > 0 || LayaEnv.isPlaying) {
                        this._changingSize = true;
                        this.owner.size(w, h);
                        this._changingSize = false;
                    }
                }

                this.applyStretchMode();
                this.drawFrame();
            }
        }
    }

    /**
     * @en The offset of the animation. Only applies when the stretch mode is AnimationStretchMode.None.
     * @zh 动画的偏移量。仅在 stretchMode 为 AnimationStretchMode.None 时生效。
     */
    get offset(): Point {
        return this._offset;
    }

    set offset(value: Readonly<Point>) {
        this._offset.copy(value);
        this.applyStretchMode();
        this.drawFrame();
    }

    /**
     * @en The color of the object.
     * @zh 对象的颜色。
     */
    get color() {
        return this._color;
    }

    set color(value: Color) {
        this._color = value;
        this.drawFrame();
    }

    get width() {
        return this._count > 0 ? this._frames[this._activeStart].sourceWidth : 0;
    }

    get height() {
        return this._count > 0 ? this._frames[this._activeStart].sourceHeight : 0;
    }

    private updateActiveRange(reset: boolean): void {
        let totalCount = this._frames.length;
        if (totalCount === 0) {
            this._activeStart = 0;
            this._count = 0;
        }
        else {
            let start = Math.min(this._rangeStart, totalCount - 1);
            let end = this._rangeEnd === -1 ? totalCount - 1 : Math.min(Math.max(this._rangeEnd, start), totalCount - 1);
            this._activeStart = start;
            this._count = end - start + 1;
        }
        if (reset) {
            this._reversed = this._wrapMode === AnimationWrapMode.Reverse;
            this._index = this._frame = this._reversed && this._count > 0 ? this._count - 1 : 0;
            this._elapsed = 0;
            if (this.owner) {
                this.updateSizeToFit();
                this.drawFrame();
            }
        }
        else if (this._count > 0) {
            this._frame = Math.max(0, Math.min(this._frame, this._count - 1));
            this._index = Math.max(0, Math.min(this._index, this._count - 1));
        }
    }

    private updateSizeToFit(): void {
        if (this._stretchMode !== AnimationStretchMode.ResizeToFit)
            return;

        let w = this.width, h = this.height;
        if (w > 0 && h > 0 || LayaEnv.isPlaying) {
            this._changingSize = true;
            this.owner.size(w, h);
            this._changingSize = false;
        }
    }

    private applyStretchMode() {
        if (this._stretchMode === AnimationStretchMode.Fill) {
            for (let cmd of this._drawCmds) {
                cmd.x = cmd.y = 0;
                cmd.width = cmd.height = 1;
                cmd.percent = true;
            }
        }
        else {
            let dx = 0, dy = 0;
            if (this._stretchMode === AnimationStretchMode.None) {
                dx = this._offset.x;
                dy = this._offset.y;
            }
            for (let cmd of this._drawCmds) {
                cmd.x = dx;
                cmd.y = dy;
                if (cmd.texture) {
                    cmd.width = cmd.texture.sourceWidth;
                    cmd.height = cmd.texture.sourceHeight;
                }
                cmd.percent = false;
            }
        }
    }

    /**
     * @en Play the animation.
     * @zh 播放动画。
     */
    play(): void {
        if (this._playing)
            return;

        this._playing = true;
        this._elapsed = 0;
        this._reversed = this._wrapMode === AnimationWrapMode.Reverse;
    }

    /**
     * @en Stop playing the animation.
     * @zh 停止播放动画。
     */
    stop() {
        this._playing = false;
        if (!LayaEnv.isPlaying) {
            this._frame = this._index;
            this.drawFrame();
        }
    }

    protected _onEnable(): void {
        if (this._autoPlay)
            this.play();
    }

    protected _onDestroy(): void {
        super._onDestroy();

        this.frames = null;
        if (this._atlas) {
            if (this.owner._getBit(NodeFlags.EDITING_NODE))
                this._atlas.off("reload", this, this.onAtlasReload);
            this._atlas = null;
        }
    }

    /**
     * @ignore
     */
    onUpdate(): void {
        if (!this._playing || this._count == 0)
            return;

        let dt: number = ILaya.timer.delta;
        if (dt > 100)
            dt = 100;
        if (this.timeScale != 1)
            dt *= this.timeScale;

        let frame = this._frame;
        let delayIndex = this._activeStart + frame;
        this._elapsed += dt;
        let tt: number = this.interval;
        if (this._reversed) {
            if (frame > 0)
                tt += this.getFrameDelay(delayIndex - 1);
            else
                tt += this.repeatDelay;
        }
        else {
            tt += this.getFrameDelay(delayIndex);
            if (frame === this._count - 1)
                tt += this.repeatDelay;
        }

        if (this._elapsed < tt)
            return;

        this._elapsed -= tt;
        if (this._elapsed > this.interval)
            this._elapsed = this.interval;

        let emit = false;

        if (this._count === 1) {
            if (!this._loop)
                this._playing = false;
            else {
                this.drawFrame();
                if (this._labels?.[0])
                    this.owner.event(Event.LABEL, this._labels[0]);
            }
            this.owner.event(Event.COMPLETE);
            return;
        }

        if (this._reversed) {
            frame--;
            if (frame < 0) {
                if (this._loop) {
                    if (this._wrapMode === AnimationWrapMode.PingPong) {
                        this._reversed = false;
                        frame = 1;
                    }
                    else
                        frame = this._count - 1;
                    emit = true;
                }
                else {
                    frame = 0;
                    this._playing = false;
                    emit = true;
                }
            }
        }
        else {
            frame++;
            if (frame > this._count - 1) {
                if (this._loop) {
                    if (this._wrapMode === AnimationWrapMode.PingPong) {
                        this._reversed = true;
                        frame = Math.max(0, this._count - 2);
                    }
                    else
                        frame = 0;
                    emit = true;
                }
                else {
                    frame = this._count - 1;
                    this._playing = false;
                    emit = true;
                }
            }
        }

        this._frame = frame;

        if (this._playing) {
            this.drawFrame();
            if (this._labels?.[frame])
                this.owner.event(Event.LABEL, this._labels[frame]);
        }

        if (emit)
            this.owner.event(Event.COMPLETE);
    }

    private getFrameDelay(index: number): number {
        if (this._delays.length === 0)
            return 0;
        if (this.frameDelaysLoop)
            index %= this._delays.length;
        return this._delays[index] || 0;
    }

    protected drawFrame(): void {
        let cmd = this._drawCmds[this._activeStart + this._frame];
        if (cmd)
            cmd.color = this._color.getABGR();
        let graphics = this.owner.graphics;
        if (cmd != this._drawCmd) {
            if (this._drawCmd && cmd && graphics.patchFrameAnimationCmd(this._drawCmd, cmd))
                this._drawCmd = cmd;
            else
                this._drawCmd = graphics.replaceCmd(this._drawCmd, cmd);
        }
        else if (this._drawCmd) {
            graphics.patchFrameAnimationCmd(this._drawCmd, this._drawCmd);
        }
    }

    /**
     * @en Atlas path.
     * @zh 图集路径。
     */
    get source(): string {
        return this._source;
    }

    set source(value: string) {
        if (value == null)
            value = "";
        this._source = value;
        this.load();
    }

    /**
     * @en The image path array of the animation.
     * @zh 动画的图片路径数组。
     */
    get images(): string[] {
        return this._images;
    }

    set images(value: string[]) {
        this._images = value;
        this.load();
    }

    private load() {
        if (this._atlas) {
            if (this.owner._getBit(NodeFlags.EDITING_NODE))
                this._atlas.off("reload", this, this.onAtlasReload);
            this._atlas = null;
        }

        if (this._source)
            this.loadAtlas(this._source);
        else if (this._images && this._images.length > 0)
            this.loadImages(this._images);
        else
            this.onLoaded(null, ++this._loadId);
    }

    protected loadImages(urls: string[]): this {
        let loadId = ++this._loadId;
        let textures = urls.map(url => Loader.getRes(url));
        if (textures.indexOf(null) === -1) {
            this.frames = textures;
            this.owner.event(Event.LOADED);
        }
        else {
            ILaya.loader.load(urls).then((textures: Array<Texture>) => {
                if (loadId != this._loadId || this.destroyed)
                    return;

                this.frames = textures;
                this.owner.event(Event.LOADED);
            });
        }

        return this;
    }

    protected loadAtlas(url: string): this {
        let loadId = ++this._loadId;
        //在反序列化时，禁止立刻设置atlas，因为autoSize值还没反序列化
        let atlas: AtlasResource = SerializeUtil.isDeserializing ? null : Loader.getRes(url, Loader.ATLAS);
        if (atlas)
            this.onLoaded(atlas, loadId);
        else
            ILaya.loader.load(url, Loader.ATLAS).then(atlas => this.onLoaded(atlas, loadId));

        return this;
    }

    /**
     * @en Set the atlas for the frame animation.
     * @param res The atlas.
     * @zh 设置帧动画的图集。
     * @param res 图集。
     */
    setAtlas(res: AtlasResource) {
        this.onLoaded(res, ++this._loadId);
    }

    private onLoaded(atlas: AtlasResource, loadId: number) {
        if (loadId != this._loadId || this.destroyed)
            return;

        this._atlas = atlas;
        if (atlas) {
            if (this.owner._getBit(NodeFlags.EDITING_NODE))
                this._atlas.on("reload", this, this.onAtlasReload);

            let ani = atlas.animation;
            if (ani) {
                this.interval = ani.interval;
                this.repeatDelay = ani.repeatDelay ?? 0;
                this.frameDelaysLoop = ani.frameDelaysLoop ?? false;
                this.wrapMode = ani.wrapMode ?? 0;
                this._delays.length = 0;
                if (ani.frameDelays)
                    this._delays.push(...ani.frameDelays);
            }
            this.frames = atlas.frames;
        }
        else
            this.frames = null;
        this.owner.event(Event.LOADED);
    }

    private onAtlasReload() {
        this.onLoaded(this._atlas, this._loadId);
    }
}
