import { SubShader } from "./SubShader";
import { ShaderCompileDefineBase, ShaderProcessInfo } from "../../webgl/utils/ShaderCompileDefineBase";
import { Shader3D, ShaderFeatureType } from "../../RenderEngine/RenderShader/Shader3D";
import { ShaderVariantCollection } from "../../RenderEngine/RenderShader/ShaderVariantCollection";
import { IShaderCompiledObj } from "../../webgl/utils/ShaderCompile";
import { LayaGL } from "../../layagl/LayaGL";
import { RenderState } from "../../RenderDriver/RenderModuleData/Design/RenderState";
import { IDefineDatas } from "../../RenderDriver/RenderModuleData/Design/IDefineDatas";
import { IShaderInstance } from "../../RenderDriver/DriverDesign/RenderDevice/IShaderInstance";
import { IShaderPassData } from "../../RenderDriver/RenderModuleData/Design/IShaderPassData";
import { ShaderMRT } from "./ShaderMRT";
import { ShaderDefine } from "../../RenderDriver/RenderModuleData/Design/ShaderDefine";


/**
 * <code>ShaderPass</code> 类用于实现ShaderPass。
 */
export class ShaderPass extends ShaderCompileDefineBase {

    private _pipelineMode: string;
    public get pipelineMode(): string {
        return this._pipelineMode;
    }
    public set pipelineMode(value: string) {
        this._pipelineMode = value;
        this.moduleData.pipelineMode = value;
    }

    set nodeCommonMap(value: Array<string>) {
        this.moduleData.nodeCommonMap = value;
    }

    get nodeCommonMap(): Array<string> {
        return this.moduleData.nodeCommonMap;
    }

    set additionShaderData(value: Array<string>) {
        this.moduleData.additionShaderData = value;
    }

    get additionShaderData(): Array<string> {
        return this.moduleData.additionShaderData;
    }

    /** 优先 ShaderPass 渲染状态 */
    private _statefirst: boolean = false;
    public get statefirst(): boolean {
        return this._statefirst;
    }
    public set statefirst(value: boolean) {
        this._statefirst = value;
        this.moduleData.statefirst = value;
    }

    moduleData: IShaderPassData;
    private _mrtTargetDefines: Map<number, ShaderDefine>;

    get attributeLocations(): Set<number> {
        return this.moduleData.attributeLocations;
    }

    set attributeLocations(value: Set<number>) {
        this.moduleData.attributeLocations = value;
    }

    /**
     * 渲染状态。
     */
    get renderState(): RenderState {
        return this.moduleData.renderState;
    }

    constructor(owner: SubShader, compiledObj: IShaderCompiledObj) {
        super(owner, owner._owner.name, compiledObj);
        this.moduleData = LayaGL.unitRenderModuleDataFactory.createShaderPass(this);
        this.moduleData.validDefine = this._validDefine;
        this.moduleData.name = this.name;
        let shaderType = owner._owner?.shaderType;
        if (shaderType === ShaderFeatureType.D2_TextureSV
            || shaderType === ShaderFeatureType.D2_primitive
            || shaderType === ShaderFeatureType.D2_BaseRenderNode2D) {
            this.moduleData.is2D = true;
        }
    }

    /**
     * @internal
     * @param is2D 
     * @param compileDefine 
     * @returns 
     */
    static createShaderInstance(shaderpass: ShaderPass, is2D: boolean, compileDefine: IDefineDatas): IShaderInstance {
        _defineStrings.length = 0;
        Shader3D._getNamesByDefineData(compileDefine, _defineStrings);

        let shaderProcessInfo: ShaderProcessInfo = {
            is2D,
            vs: shaderpass._VS,
            ps: shaderpass._PS,
            attributeMap: shaderpass._owner._attributeMap,
            uniformMap: shaderpass._owner._uniformMap,
            defineString: _defineStrings.slice(),
        };

        return ShaderPass.createShaderInstanceByInfo(shaderpass, shaderProcessInfo);
    }

    /** @internal 统一处理各后端的图形 Shader 实例创建诊断。 */
    static createShaderInstanceByInfo(shaderpass: ShaderPass, shaderProcessInfo: ShaderProcessInfo): IShaderInstance {
        const defineString = shaderProcessInfo.defineString.slice();
        const processInfo = { ...shaderProcessInfo, defineString };

        if (Shader3D.compileVerbose) {
            const shaderName = shaderpass._owner?._owner?.name || "unknown";
            console.info("compile shader:", shaderName, defineString.join(","));
        }

        Shader3D.compiledCount++;

        return LayaGL.renderDeviceFactory.createShaderInstance(processInfo, shaderpass);
    }

    /** @internal 将缓存树扩容到新层数，并保留每个旧叶子的实例身份。 */
    static resizeCacheShaderMap(cacheMap: any, hierarchy: number, currentHierarchy: number, resizeLength: number): void {
        const end = currentHierarchy - 1;
        if (hierarchy === end) {
            const extraLevels = resizeLength - currentHierarchy;
            if (extraLevels <= 0)
                return;

            for (const key of Object.keys(cacheMap)) {
                let shader = cacheMap[key];
                for (let i = 0; i < extraLevels; i++)
                    shader = { 0: shader };
                cacheMap[key] = shader;
            }
            return;
        }

        const nextHierarchy = hierarchy + 1;
        for (const key of Object.keys(cacheMap))
            ShaderPass.resizeCacheShaderMap(cacheMap[key], nextHierarchy, currentHierarchy, resizeLength);
    }

    /**
     * @override
     * @internal
     */
    withCompile(compileDefine: IDefineDatas, is2D: boolean = false, mrtTargetCount?: number): IShaderInstance {
        // 运行时由实际绑定的目标控制 MRT；离线编译保留请求的目标变体。
        if (mrtTargetCount !== undefined) {
            const mrtDefine = Shader3D.getDefineByName(ShaderMRT.defineName);
            if (mrtTargetCount > 0) compileDefine.add(mrtDefine);
            else compileDefine.remove(mrtDefine);
        } else {
            // 过滤有效宏前读取槽位跨度，保留离线预热的目标布局。
            const defineNames: string[] = [];
            Shader3D._getNamesByDefineData(compileDefine, defineNames);
            mrtTargetCount = ShaderMRT.getTargetCount(defineNames);
        }
        if (this._mrtTargetDefines) {
            for (const define of this._mrtTargetDefines.values()) compileDefine.remove(define);
        }
        if (mrtTargetCount > 0) {
            this._mrtTargetDefines ||= new Map();
            let define = this._mrtTargetDefines.get(mrtTargetCount);
            if (!define) {
                define = Shader3D.getDefineByName(ShaderMRT.targetDefinePrefix + mrtTargetCount);
                this._mrtTargetDefines.set(mrtTargetCount, define);
                this._validDefine.add(define);
            }
            compileDefine.add(define);
        }
        var shader: IShaderInstance = this.moduleData.getCacheShader(compileDefine);
        if (shader)
            return shader;
        shader = ShaderPass.createShaderInstance(this, is2D, compileDefine);
        this.moduleData.setCacheShader(compileDefine, shader);
        return shader;
    }

    withComplieByBin(compileDefine: IDefineDatas, is2D: boolean = false, buffer: ArrayBuffer) {
        var shader: IShaderInstance = this.moduleData.getCacheShader(compileDefine);
        if (shader)
            return shader;
        //TODO
        //shader = ShaderPass.createShaderInstance(this, is2D, compileDefine);
        this.moduleData.setCacheShader(compileDefine, shader);
        return null;
    }
}

const _defineStrings: Array<string> = [];
