import { ILaya, Mutable } from "../../ILaya";
import { Laya } from "../../Laya";
import { Input } from "../display/Input";
import { type Stage } from "../display/Stage";
import { Text } from "../display/Text";
import { Event } from "../events/Event";
import { InputManager } from "../events/InputManager";
import { Browser } from "../utils/Browser";
import { SpriteUtils } from "../utils/SpriteUtils";
import { PAL } from "./PlatformAdapters";

export interface TextInputCapabilities {
    presentation: "inline" | "native-panel" | "platform-keyboard";
    selection: boolean;
    inputTypes: readonly string[];
}

/**
 * @ignore
 */
export class TextInputAdapter {
    readonly target: Input;

    protected _eInput: HTMLInputElement;
    protected _ePassword: HTMLInputElement;
    protected _eTextArea: HTMLTextAreaElement;
    protected _visEle: HTMLInputElement | HTMLTextAreaElement;
    protected _container: HTMLDivElement;
    protected _promptStyleDOM: HTMLElement;
    protected _restrictPattern: RegExp;
    protected _enterEvent: Event;
    protected _lastTransform: { x: number, y: number, width: number, height: number, scaleX: number, scaleY: number };
    protected _beginFlag: number = 0;
    private _beginTarget: Input;
    private _selectionReady: boolean = false;
    private _selectionSession: number = 0;
    private _pendingSelection: { target: Input, start: number, end: number };
    private _opening: Promise<void> = Promise.resolve();
    private _closing: Promise<void> = Promise.resolve();
    private _touchReleased: boolean = false;
    private _composing: boolean = false;

    get capabilities(): TextInputCapabilities {
        return {
            presentation: "inline", selection: true,
            inputTypes: ["text", "password", "email", "url", "number", "range", "date", "month", "week", "time", "datetime", "datetime-local", "search"]
        };
    }

    protected get sessionId(): number { return this._selectionSession; }

    /**
     * If true, the input box will be displayed inline with the canvas.
     * If false, use a pop-up keyboard to enter text.
     */
    protected _editInline: boolean = true;

    constructor() {
        this._enterEvent = new Event();
        this._lastTransform = <any>{};

        Laya.addAfterInitCallback(() => {
            ILaya.stage.on(Event.MOUSE_UP, this, this.onTouchEnd);
            InputManager.onMouseDownCapture.add(this.onTouchBegin, this);
        });
    }

    begin(target: Input, fromTouchBegin?: boolean): Promise<void> {
        if (this.target === target || this._beginTarget === target)
            return this._opening;
        try {
            target.prepareInput();
        } catch (error) {
            target.event(Event.ERROR, error);
            return Promise.reject(error);
        }
        const ending = this.target || this._beginTarget ? this.end(false, true) : this._closing;
        const session = ++this._selectionSession;
        this._beginFlag = 1;
        this._selectionReady = false;
        this._beginTarget = target;
        this._touchReleased = !fromTouchBegin;
        const current = () => session === this._selectionSession && !target.destroyed;
        const opening = ending.then(async () => {
            if (!current()) return;
            target.prepareInput();
            (<Mutable<this>>this).target = target;
            (<Mutable<Stage>>ILaya.stage).focus = target;
            this.updateRestrictPattern();
            this._lastTransform.x = null;
            target.on(Event.UNDISPLAY, this, this.onTargetUndisplay);
            await this.onBegin();
            if (!current()) return;
            target.prepareInput();
            if (this._editInline) {
                target.hideText(true);
                ILaya.stage.on(Event.KEY_DOWN, this, this.onKeyDown);
            }
            target.event(Event.FOCUS);
            if (!current() || this.target !== target) return;
            if (this._touchReleased) {
                this._beginFlag = 0;
                await this.showKeyboard();
            } else {
                this._beginFlag = 2;
            }
        });
        this._opening = opening;
        return opening.catch(error => {
            if (session === this._selectionSession) this.fail(error);
            throw error;
        });
    }

    end(complete?: boolean, switching?: boolean): Promise<void> {
        const target = this.target;
        const revision = target?.inputRevision;
        const pending = this._beginTarget;
        this._selectionReady = false;
        this._selectionSession++;
        this._beginTarget = null;
        this._pendingSelection = null;
        this._beginFlag = 0;
        if (!target && !pending) return this._closing;
        (<Mutable<this>>this).target = null;
        if (ILaya.stage.focus === target) (<Mutable<Stage>>ILaya.stage).focus = null;
        if (target) target.off(Event.UNDISPLAY, this, this.onTargetUndisplay);
        ILaya.stage.off(Event.KEY_DOWN, this, this.onKeyDown);
        const closing = this._opening.then(() => {}, () => {}).then(async () => {
            if (!target) return;
            try {
                await this.onEnd(target, !!complete, !!switching, revision);
            } finally {
                if (!target.destroyed) {
                    if (this._editInline) target.hideText(false);
                    if (target.editable) target.event(Event.CHANGE);
                    if (!target.destroyed) target.event(Event.BLUR);
                }
            }
        });
        // Wait for cleanup to settle; the returned operation still rejects on failure.
        this._closing = closing.catch(error => {
            if (target && !target.destroyed) target.event(Event.ERROR, error);
        });
        return closing;
    }

    protected fail(error: unknown): void {
        const target = this.target || this._beginTarget;
        this.end().catch(closeError => console.error(closeError));
        if (target && !target.destroyed) target.event(Event.ERROR, error);
    }

    /** End only this target, including an asynchronous begin that has not acquired focus. */
    endFor(target: Input): Promise<void> {
        return this.target === target || this._beginTarget === target ? this.end() : Promise.resolve();
    }

    private onTargetUndisplay(): void {
        this.end().catch(error => console.error(error));
    }

    protected onBegin(): Promise<void> {
        this.showInputElement();

        let ele = this._visEle;
        let target = this.target;

        if (ele instanceof HTMLInputElement)
            ele.type = target.type;
        ele.inputMode = "";
        ele.readOnly = !target.editable;
        ele.maxLength = target.maxChars <= 0 ? 1E5 : target.maxChars;
        ele.enterKeyHint = target.confirmType;
        target.configureInputElement(ele);
        ele.value = this.target.text;
        ele.placeholder = target.localizedPrompt;

        let style = ele.style;
        style.fontFamily = target.realFont;
        style.color = target.color;
        style.fontSize = target.fontSize + 'px';
        style.whiteSpace = (target.wordWrap ? "pre-wrap" : "nowrap");
        style.lineHeight = (target.leading + target.fontSize) + "px";
        style.fontStyle = (target.italic ? "italic" : "normal");
        style.fontWeight = (target.bold ? "bold" : "normal");
        style.textAlign = target.align;
        style.letterSpacing = target.letterSpacing + 'px';
        style.padding = "0 0";
        style.direction = Text.RightToLeft ? "rtl" : "";

        this.setPromptColor();
        this.syncTransform();
        if (this._editInline)
            ILaya.systemTimer.frameLoop(1, this, this.syncTransform);

        return Promise.resolve();
    }

    //和onBegin区别在于，onBegin在touchBegin调用，这个在touchEnd调用
    protected onCanShowKeyboard(): Promise<void> {
        if (this._visEle)
            this._visEle.focus();
        return Promise.resolve();
    }

    protected onEnd(target: Input, complete: boolean, switching: boolean, revision: number): Promise<void> {
        Browser.document.body.scrollTop = 0;
        if (this._visEle) {
            const value = this._visEle.value;
            this._visEle.blur();
            this.hideInputElement();
            this._visEle = null;
            this._composing = false;
            ILaya.systemTimer.clear(this, this.syncTransform);
            if (!target.destroyed && target.inputRevision === revision) {
                const previous = target.getInputText();
                target.setInputText(value);
                if (target.getInputText() !== previous) target.event(Event.INPUT);
            }
        }

        return Promise.resolve();
    }

    syncText() {
        if (this._visEle && this._beginFlag === 0 && !this._composing)
            this.updateTargetText(this._visEle.value);
    }

    setText(value: string) {
        if (this._visEle)
            this._visEle.value = value;
    }

    setSelection(startIndex: number, endIndex: number): void {
        if (!this.capabilities.selection || !this._visEle)
            throw new Error("Text selection is not available");
        this._visEle.setSelectionRange(startIndex, endIndex < 0 ? this._visEle.value.length : endIndex);
    }

    /** @internal Set selection after the target's input element is ready. */
    setSelectionFor(target: Input, startIndex: number, endIndex: number): void {
        if (this.target === target && this._selectionReady) {
            this._pendingSelection = null;
            this.setSelection(startIndex, endIndex);
            return;
        }

        this.begin(target).catch(error => console.error(error));
        if (this.target === target || this._beginTarget === target)
            this._pendingSelection = { target, start: startIndex, end: endIndex };
    }

    private showKeyboard(): Promise<void> {
        const target = this.target;
        const session = this._selectionSession;
        return this.onCanShowKeyboard().then(() => {
            if (!target || this.target !== target || this._selectionSession !== session)
                return;
            this._selectionReady = true;
            this._beginTarget = null;
            const selection = this._pendingSelection;
            this._pendingSelection = null;
            if (selection && selection.target === target)
                this.setSelection(selection.start, selection.end);
        });
    }

    private onTouchBegin(): void {
        let lastFocus = ILaya.stage.focus;
        let touchTarget = InputManager.touchTarget;
        if (lastFocus != touchTarget) {
            if (touchTarget instanceof Input)
                this.begin(touchTarget, true).catch(error => console.error(error));
            else if (lastFocus instanceof Input || this._beginTarget)
                this.end().catch(error => console.error(error));
        }
    }

    private onTouchEnd(): void {
        this._touchReleased = true;
        if (this._beginFlag === 2) {
            this._beginFlag = 0;
            const opening = this.showKeyboard();
            this._opening = opening;
            opening.catch(error => this.fail(error));
        }
    }

    protected setPromptColor(): void {
        // 创建style标签
        this._promptStyleDOM = Browser.document.getElementById("promptStyle");
        if (!this._promptStyleDOM) {
            this._promptStyleDOM = Browser.document.createElement("style");
            this._promptStyleDOM.setAttribute("id", "promptStyle");
            Browser.document.head.appendChild(this._promptStyleDOM);
        }

        let color = this.target.promptColor;

        // 设置style标签
        this._promptStyleDOM.innerText = `input::-webkit-input-placeholder, textarea::-webkit-input-placeholder {
                color: ${color}
            }
            input:-moz-placeholder, textarea:-moz-placeholder {
                color: ${color}
            }
            input::-moz-placeholder, textarea::-moz-placeholder {
                color: ${color}
            }
            input:-ms-input-placeholder, textarea:-ms-input-placeholder {
                color: ${color}
            }
        `;
    }

    protected updateRestrictPattern(): void {
        let value = this.target.restrict;
        // H5保存RegExp
        if (value) {
            value = "[^" + value + "]";

            // 如果pattern为^\00-\FF，则我们需要的正则表达式是\00-\FF
            if (value.indexOf("^^") > -1)
                value = value.replace("^^", "");

            this._restrictPattern = new RegExp(value, "g");
        } else
            this._restrictPattern = null;
    }

    protected validateText(str: string): string {
        // The target owns text normalization/validation through setInputText.
        // 对输入字符进行限制
        if (this._restrictPattern) {
            // 部分输入法兼容
            str = str.replace(/\u2006|\x27/g, "");
            if (this._restrictPattern.test(str)) {
                str = str.replace(this._restrictPattern, "");
            }
        }

        return str;
    }

    protected showInputElement(): void {
        if (!this._eInput)
            this.createElements();

        let password = this.target.type === "password";
        let multiline = this.target.multiline && !password;
        let inputElement = (multiline ? this._eTextArea : password ? this._ePassword : this._eInput);
        this._visEle = inputElement;
        this._container.appendChild(inputElement);
    }

    protected hideInputElement(): void {
        if (this._visEle && this._visEle.parentElement)
            this._visEle.remove();
    }

    protected updateTargetText(value: string): boolean {
        let target = this.target;
        const previous = target.getInputText();
        target.setInputText(value);
        return target.getInputText() !== previous;
    }

    protected getTargetTransform() {
        let padding = this.target.padding;
        let { x, y, scaleX, scaleY } = SpriteUtils.getTransformRelativeToWindow(this.target, padding[3], padding[0]);
        let w = this.target.width - padding[1] - padding[3];
        let h = this.target.height - padding[0] - padding[2];

        let t = this._lastTransform;
        if (x !== t.x || y !== t.y || w !== t.width || h !== t.height || scaleX !== t.scaleX || scaleY !== t.scaleY) {
            t.x = x;
            t.y = y;
            t.width = w;
            t.height = h;
            t.scaleX = scaleX;
            t.scaleY = scaleY;
            return t;
        }
        else
            return null;
    }

    protected syncTransform(): void {
        let t = this.getTargetTransform();
        if (t != null) {
            let style = this._visEle.style;

            style.width = t.width + 'px';
            style.height = t.height + 'px';
            PAL.browser.setStyleTransform(style, "scale(" + t.scaleX + "," + t.scaleY + ") rotate(" + (ILaya.stage.canvasDegree) + "deg)");

            this._container.style.left = t.x + 'px';
            this._container.style.top = t.y + 'px';
        }
    }

    protected createElements(): void {
        this._container = Browser.document.createElement("div");
        Browser.container.appendChild(this._container);

        let style = this._container.style;
        style.position = "absolute";
        style.zIndex = '1E5';

        this.initElement(this._eTextArea = Browser.document.createElement("textarea"));
        this.initElement(this._eInput = Browser.document.createElement("input"));
        this.initElement(this._ePassword = Browser.document.createElement("input"));
    }

    protected initElement(input: HTMLInputElement | HTMLTextAreaElement): void {
        let style = input.style;
        style.cssText = "position:absolute;overflow:hidden;resize:none;";
        style.resize = 'none';
        style.backgroundColor = 'transparent';
        style.border = 'none';
        style.outline = 'none';
        style.zIndex = '1';
        PAL.browser.setStyleTransformOrigin(style, "0 0");

        input.addEventListener("compositionstart", () => this._composing = true);
        input.addEventListener('input', ev => !this._composing && !(<InputEvent>ev).isComposing && this.processInputting(ev));
        input.addEventListener("compositionend", ev => { this._composing = false; this.processInputting(ev); });

        input.addEventListener('mousemove', ev => this.stopEvent(ev), { passive: false });
        input.addEventListener('mousedown', ev => this.stopEvent(ev), { passive: false });
        input.addEventListener('touchmove', ev => this.stopEvent(ev), { passive: false });
    }

    protected processInputting(ev: globalThis.Event): void {
        if (!this.target)
            return;

        let ele = <HTMLInputElement | HTMLTextAreaElement>ev.target;
        const target = this.target;
        try {
            let value = this.validateText(ele.value);
            const changed = this.updateTargetText(value);
            if (this.target !== target) return;
            const committed = target.getInputText();
            if (ele.value !== committed) ele.value = committed;
            if (changed) target.event(Event.INPUT);
        } catch (error) { this.fail(error); }
    }

    protected stopEvent(e: any): void {
        if (e.type == 'touchmove')
            e.preventDefault();
        e.stopPropagation && e.stopPropagation();
    }

    protected onKeyDown(e: KeyboardEvent): void {
        if (!this._composing && (e.key === "Enter" || e.key === "NumpadEnter")) {
            let target = this.target;
            if (!target.multiline) {
                e.preventDefault();

                this._enterEvent.setTo(Event.ENTER, this.target, this.target);
                target.event(Event.ENTER, this._enterEvent);
                if (!this._enterEvent._defaultPrevented && this.target === target)
                    this.end().catch(error => console.error(error));
            }
        }
    }
}

PAL.register("textInput", TextInputAdapter);
