import { Matrix } from "../../maths/Matrix";
import { Rectangle } from "../../maths/Rectangle";
import { Texture } from "../../resource/Texture";
import { ColorUtils } from "../../utils/ColorUtils";
import { ClassUtils } from "../../utils/ClassUtils";
import { Pool } from "../../utils/Pool";
import type { GraphicsCommandInfo, IGraphicsCmd, IGraphicsBoundsAssembler, IGraphicsCommandExecutor } from "../IGraphics";

const CLASS_NAME = "DrawTrianglesMSDFCmd";

/** @internal Low-level MSDF mesh command consumed by the new Graphics compiler. */
export class DrawTrianglesMSDFCmd implements IGraphicsCmd {
    static readonly ID = CLASS_NAME;
    static unpackPackedParameter(value: number): [number, number, number, number] {
        value = value >>> 0;
        return [value & 0xff, (value >>> 8) & 0xff, (value >>> 16) & 0xff, (value >>> 24) & 0xff];
    }
    _texture: Texture | null = null;
    x = 0;
    y = 0;
    vertices: ArrayLike<number> = null;
    uvs: ArrayLike<number> = null;
    indices: ArrayLike<number> = null;
    fillColors: ArrayLike<number> = null;
    outlineColors: ArrayLike<number> = null;
    glowColors: ArrayLike<number> = null;
    shadowColors: ArrayLike<number> = null;
    packedParamsA: ArrayLike<number> = null;
    packedParamsB: ArrayLike<number> = null;
    matrix: Matrix | null = null;
    alpha = 1;
    color = 0xffffffff;
    blendMode: string | null = null;

    static create(texture: Texture, x: number, y: number, vertices: ArrayLike<number>, uvs: ArrayLike<number>, indices: ArrayLike<number>,
        fillColors: ArrayLike<number>, outlineColors: ArrayLike<number>, glowColors: ArrayLike<number>, shadowColors: ArrayLike<number>,
        packedParamsA: ArrayLike<number>, packedParamsB: ArrayLike<number>, matrix: Matrix | null = null, alpha = 1,
        color: string | number | null = null, blendMode: string | null = null): DrawTrianglesMSDFCmd {
        const vertexCount = vertices ? vertices.length >> 1 : 0;
        if (!packedParamsB || packedParamsB.length < vertexCount)
            throw new RangeError("MSDF packedParamsB must contain vertexCount entries");
        for (let i = 0; i < vertexCount; i++)
            if ((packedParamsB[i] >>> 24) !== 0)
                throw new Error(`MSDF packedParamsB[${i}] high 8 bits must be zero`);
        const cmd = Pool.getItemByClass(CLASS_NAME, DrawTrianglesMSDFCmd);
        cmd.texture = texture;
        cmd.x = x;
        cmd.y = y;
        cmd.vertices = vertices;
        cmd.uvs = uvs;
        cmd.indices = indices;
        cmd.fillColors = fillColors;
        cmd.outlineColors = outlineColors;
        cmd.glowColors = glowColors;
        cmd.shadowColors = shadowColors;
        cmd.packedParamsA = packedParamsA;
        cmd.packedParamsB = packedParamsB;
        cmd.matrix = matrix;
        cmd.alpha = alpha;
        cmd.color = color == null ? 0xffffffff : ColorUtils.create(color).numColor;
        cmd.blendMode = blendMode;
        return cmd;
    }

    get texture(): Texture | null { return this._texture; }
    set texture(value: Texture | null) {
        value?._addReference();
        this._texture?._removeReference();
        this._texture = value;
    }

    run(executor: IGraphicsCommandExecutor, gx: number, gy: number): void {
        executor.drawTrianglesMSDF(this.texture!, this.x + gx, this.y + gy, this.vertices, this.uvs, this.indices,
            this.fillColors, this.outlineColors, this.glowColors, this.shadowColors, this.packedParamsA, this.packedParamsB,
            this.matrix, this.alpha, this.blendMode, this.color);
    }

    get cmdID(): string { return DrawTrianglesMSDFCmd.ID; }

    getGraphicsCommandInfo(out: GraphicsCommandInfo): GraphicsCommandInfo {
        out.dependency = 0;
        out.layoutRefresh = 0;
        out.scaleTessellationKey = 0;
        out.isStateCommand = false;
        return out;
    }

    getBounds(assembler: IGraphicsBoundsAssembler): void {
        if (!this.vertices || this.vertices.length < 2)
            return;
        const transform = this.matrix;
        const tx = this.x, ty = this.y;
        const firstX = this.vertices[0], firstY = this.vertices[1];
        let minX = transform ? firstX * transform.a + firstY * transform.c + transform.tx + tx : firstX + tx;
        let minY = transform ? firstX * transform.b + firstY * transform.d + transform.ty + ty : firstY + ty;
        let maxX = minX, maxY = minY;
        for (let i = 2; i + 1 < this.vertices.length; i += 2) {
            const vx = this.vertices[i], vy = this.vertices[i + 1];
            const px = transform ? vx * transform.a + vy * transform.c + transform.tx + tx : vx + tx;
            const py = transform ? vx * transform.b + vy * transform.d + transform.ty + ty : vy + ty;
            minX = Math.min(minX, px);
            minY = Math.min(minY, py);
            maxX = Math.max(maxX, px);
            maxY = Math.max(maxY, py);
        }
        Rectangle.TEMP.setTo(minX, minY, maxX - minX, maxY - minY).getBoundPoints(assembler.points);
    }

    recover(): void {
        this.texture = null;
        this.vertices = this.uvs = this.indices = null;
        this.fillColors = this.outlineColors = this.glowColors = this.shadowColors = null;
        this.packedParamsA = this.packedParamsB = null;
        this.matrix = null;
        this.blendMode = null;
        Pool.recover(CLASS_NAME, this);
    }
}

ClassUtils.regClass(CLASS_NAME, DrawTrianglesMSDFCmd);
