export enum ENodeCustomData {
    custom_0,
    custom_1,
    custom_2
}


/**
 * 3D Render Node
 * @ignore
 * @blueprintIgnore @blueprintIgnoreSubclasses
 */
export interface IBaseRenderNode {
    renderNodeType: number;//Flag
    transform: Transform3D;
    distanceForSort: number;
    sortingFudge: number;
    /** Renderer order within a render queue; lower values are submitted first. */
    renderOrder: number;
    castShadow: boolean;
    receiveShadow: boolean;
    enable: boolean;
    renderbitFlag: number;
    //裁剪范围
    visibalRangeBit: number;
    visibalMin: number;
    visibalMax: number;
    layer: number;
    bounds: Bounds;
    baseGeometryBounds: Bounds;
    boundsChange: boolean;
    staticMask: number;
    shaderData: ShaderData;
    additionShaderData: Map<string, ShaderData>;
    lightmapIndex: number;
    lightmap: ILightMapData;
    probeReflection: IReflectionProbeData;
    reflectionMode: number;
    volumetricGI: IVolumetricGIData;
    lightProbUpdateMark: number;
    irradientMode: IrradianceMode;
    ismoved: Vector2;
    perCameraUpdate: boolean;
    set_renderUpdatePreCall(call: any, fun: any): void;
    set_caculateBoundingBox(call: any, fun: any): void;
    /**
     * LayaX 专有（Web/RT 驱动不实现，调用处用 `?.`）：bounds 来源模式下沉 ECS。
     * 0=Auto(geometryBounds×WorldMat) 1=Explicit(直推世界AABB) 2=AlwaysVisible(不剔除)
     */
    setBoundsMode?(mode: number): void;
    /** LayaX 专有：世界空间加性 pad（Auto 模式算完 world AABB 后叠加，如粒子重力偏移）。 */
    setBoundsWorldPad?(minX: number, minY: number, minZ: number, maxX: number, maxY: number, maxZ: number): void;
    /** LayaX 专有：Explicit 模式直推世界 AABB（拖尾/UI3D 等 ECS 无法自算的）。 */
    setWorldBounds?(minX: number, minY: number, minZ: number, maxX: number, maxY: number, maxZ: number): void;
    /** LayaX 专有：退订每帧 native bounds 回调（bounds 输入改经 ECS 下沉）。 */
    disableNativeBoundsCallback?(): void;
    /**
     * @param value 
     */
    setRenderelements(value: IRenderElement3D[], deferUntilSubmit?: boolean): void;
    /**
     * @internal
     * @param value 
     */
    setLightmapScaleOffset(value: Vector4): void;
    /**
     * @internal
     * @param value 
     */
    setCommonUniformMap(value: string[]): void;

    /**
     * 设置基于RenderNode的渲染数据
     * @param dataSlot 
     * @param data 
     */
    setNodeCustomData(dataSlot: ENodeCustomData, data: number): void;
    /**
     * @override
     * @internal
     */
    destroy(): void;
    _applyLightProb(): void;
    _applyReflection(): void;
}

export interface IMeshRenderNode extends IBaseRenderNode {
}

export interface ISkinRenderNode extends IMeshRenderNode {
    computeSkinnedData(): void;
    setRootBoneTransfom(value: Sprite3D): void;
    setOwnerTransform(value: Sprite3D): void;
    setCacheMesh(cacheMesh: Mesh): void;
    setBones(value: Sprite3D[]): void;
    setSkinnedData(value: any[]): void;
}

export interface ISimpleSkinRenderNode extends IBaseRenderNode {
    setSimpleAnimatorParams(value: Vector4): void;
}

