import { IResourceLoader, ILoadTask, Loader, ILoadOptions } from "../net/Loader";
import { URL } from "../net/URL";
import { AssetDb } from "../resource/AssetDb";
import { Prefab } from "../resource/HierarchyResource";
import { IHierarchyParserAPI, IPrefabDependency, IPrefabDependencyURL, PrefabImpl } from "../resource/PrefabImpl";

interface PrefabDependencyRequest {
    readonly link: string | IPrefabDependencyURL;
    readonly url: string;
    readonly optional: boolean;
    readonly preload: boolean;
}

export class HierarchyLoader implements IResourceLoader {

    load(task: ILoadTask) {
        let url = task.url;
        let fromDCC = task.ext == "gltf" || task.ext == "fbx" || task.ext == "glb" || task.ext == "obj";
        if (fromDCC)
            url = AssetDb.inst.getSubAssetURL(url, task.uuid, "0", "lh");
        return task.loader.fetch(url, "json", task.progress.createCallback(0.2), task.options).then(data => {
            if (!data)
                return null;

            if (data._$ver != null)
                return this._load(PrefabImpl.v3, task, data, fromDCC);
            else if (task.ext == "ls" || task.ext == "lh")
                return this._load(PrefabImpl.v2, task, data, fromDCC);
            else if (task.ext == "scene" || task.ext == "prefab")
                return this._load(PrefabImpl.legacySceneOrPrefab, task, data, fromDCC);
            else
                return null;
        });
    }

    protected _load(api: IHierarchyParserAPI, task: ILoadTask, data: any, fromDCC: boolean): Promise<Prefab> {
        let basePath = URL.getPath(task.url);
        let links = api.collectResourceLinks(data, basePath);
        let dependencyRequests: PrefabDependencyRequest[] = links.map(link => {
            const entry = typeof link === "string" ? null : link;
            const url = typeof link === "string" ? link : link.url;
            if (!url)
                throw new Error(`Prefab dependency URL is missing (prefab: ${task.url})`);
            return {
                link,
                url,
                optional: entry?.optional === true,
                preload: entry?.preload === true,
            };
        });
        let options: ILoadOptions = Object.assign({}, task.options);
        options.initiator = task;
        delete options.cache;
        delete options.ignoreCache;
        const loadDependencies = (requests: PrefabDependencyRequest[], progressWeight?: number): Promise<IPrefabDependency[]> => {
            const progress = progressWeight == null
                ? task.progress.createCallback()
                : task.progress.createCallback(progressWeight);
            return task.loader.load(requests.map(request => request.link), options, progress).then((resources: unknown) => {
                if (!Array.isArray(resources) || resources.length !== requests.length) {
                    const actualCount = Array.isArray(resources) ? resources.length : "non-array";
                    throw new Error(`Prefab dependency result count mismatch during load: ${actualCount}/${requests.length} (prefab: ${task.url})`);
                }
                return requests.map((request, index) => ({
                    url: request.url,
                    optional: request.optional,
                    resource: resources[index],
                }));
            });
        };
        let preloadRequests = dependencyRequests.filter(request => request.preload);
        let p: Promise<IPrefabDependency[]>;
        if (preloadRequests.length > 0) {
            let remainingRequests = dependencyRequests.filter(request => !request.preload);
            p = loadDependencies(preloadRequests, 0.2).then(preloadDependencies => {
                return loadDependencies(remainingRequests, 0.8).then(dependencies => {
                    preloadDependencies.push(...dependencies);
                    return preloadDependencies;
                });
            });
        }
        else {
            p = loadDependencies(dependencyRequests);
        }

        return p.then(dependencies => {
            const dependencyResources = PrefabImpl._validateDependencies(dependencies, task.url, "load");
            let res = new PrefabImpl(api, data);
            res.fromDCC = fromDCC;
            res.onLoad();
            res._setDependencies(dependencies);
            res.addDeps(dependencyResources);
            return res;
        });
    }
}

Loader.registerLoader(["lh", "ls", "scene", "prefab"], HierarchyLoader, Loader.HIERARCHY);
