import { Node } from "../display/Node";
import { Sprite } from "../display/Sprite";
import { HierarchyParser } from "../loaders/HierarchyParser";
import { ILoadURL } from "../net/Loader";
import { ClassUtils } from "../utils/ClassUtils";
import { Prefab } from "./HierarchyResource";
import { Resource } from "./Resource";

/**
 * @en A resource link collected while loading a prefab.
 * @zh Prefab 加载期间收集到的资源链接。
 */
export interface IPrefabDependencyURL extends ILoadURL {
    /** @en Load this dependency before the remaining links. @zh 在其它链接之前加载此依赖。 */
    preload?: boolean;
    /** @en Whether a missing result is allowed. @zh 是否允许加载结果缺失。 */
    optional?: boolean;
}

/** @internal */
export interface IPrefabDependency {
    readonly url: string;
    readonly optional: boolean;
    readonly resource: unknown;
}

interface PrefabNodeData {
    _$id?: string;
    _$child?: PrefabNodeData[];
}

/**
 * @en Options used while parsing a hierarchy.
 * @zh 解析层级结构时使用的选项。
 */
export interface IHierarchyParseOptions extends Record<string, any> {
    /**
     * @en Determines whether a component should be created for the node.
     * @zh 决定是否为节点创建指定组件。
     */
    shouldCreateComponent?: (nodeData: any, compData: any) => boolean;
    /** @internal @en The source prefab being parsed. @zh 当前正在解析的来源 Prefab。 */
    prefab?: PrefabImpl;
}

/**
 * @en Hierarchy parser API.
 * @zh 层次结构分析器 API。
 */
export interface IHierarchyParserAPI {
    /**
     * @en Collect resource links required by the data.
     * @param data The data object to process.
     * @param basePath The base path used to resolve resource links.
     * @returns An array of strings or ILoadURL objects representing the resource links.
     * @zh 收集数据所需的资源链接。
     * @param data 需要处理的数据对象。
     * @param basePath 用于解析资源链接的基础路径。
     * @returns 返回表示资源链接的字符串或 ILoadURL 对象数组。
     */
    collectResourceLinks: (data: any, basePath: string) => (string | IPrefabDependencyURL)[],
    /**
     * @en Parse the data and create a hierarchy of nodes.
     * @param data The data object to parse.
     * @param options Optional settings for parsing.
     * @param errors Array to store any errors encountered during parsing.
     * @returns An array of nodes or a single node if only one is created.
     * @zh 解析数据并创建节点的层次结构。
     * @param data 需要解析的数据对象。
     * @param options 解析的可选设置。
     * @param errors 存储解析过程中遇到的错误的数组。
     * @zh 返回节点数组或如果只创建了一个节点，则返回单个节点。
     */
    parse: (data: any, options?: IHierarchyParseOptions, errors?: Array<any>) => Array<Node> | Node;
}

/**
 * @en This class is used to import prefabs.
 * @zh 该类用于导入预制体。
 * @blueprintIgnore
 */
export class PrefabImpl extends Prefab {

    static v3: IHierarchyParserAPI = HierarchyParser;
    static v2: IHierarchyParserAPI = null;
    static legacySceneOrPrefab: IHierarchyParserAPI & {
        createByData(root: Sprite, uiView: any): Sprite;
        createComp(uiView: any, comp: Sprite, view: Sprite, dataMap: any[], initTool?: any): any;
    };

    /**
     * @en The prefab data.
     * @zh 预制体数据。
     */
    data: any;
    /**
     * @en The hierarchy parser API used to parse the prefab data.
     * @zh 用于解析预制体数据的层次结构 API。
     */
    api: IHierarchyParserAPI;

    private _dependencySnapshot: ReadonlyArray<IPrefabDependency> = [];
    private readonly _fragments: Map<string, PrefabFragment> = new Map();

    /**
     * @en Create an instance of the PrefabImpl class.
     * @param api The hierarchy parser API.
     * @param data The data to initialize the prefab instance with.
     * @zh 创建 PrefabImpl 类的实例。
     * @param api 层次结构API
     * @param data 用于初始化预制体实例的数据。
     */
    constructor(api: IHierarchyParserAPI | null, data: any) {
        super();

        this.api = api || PrefabImpl.v3;
        this.data = data;
    }

    /** @internal */
    static _validateDependencies(dependencies: ReadonlyArray<IPrefabDependency>, prefabURL: string, phase: "load" | "create"): Resource[] {
        const resources: Resource[] = [];
        for (const dependency of dependencies) {
            const resource = dependency.resource;
            if (resource == null) {
                if (dependency.optional)
                    continue;
                throw new Error(`Prefab dependency is missing during ${phase}: ${dependency.url} (prefab: ${prefabURL})`);
            }
            if (!(resource instanceof Resource))
                throw new Error(`Prefab dependency has invalid type during ${phase}: ${dependency.url} (prefab: ${prefabURL})`);
            if (resource.destroyed)
                throw new Error(`Prefab dependency has been destroyed during ${phase}: ${dependency.url} (prefab: ${prefabURL})`);
            resources.push(resource);
        }
        return resources;
    }

    /** @internal */
    _setDependencies(dependencies: ReadonlyArray<IPrefabDependency>): void {
        this._dependencySnapshot = dependencies.map(dependency => ({ ...dependency }));
    }

    /**
     * @en Gets the reusable fragment for a node ID in this prefab.
     * @zh 获取此 Prefab 中指定节点 ID 对应的可复用片段。
     */
    getFragment(id: string | null): PrefabFragment {
        if (this.destroyed)
            throw new Error(`Prefab has been destroyed: ${this.url}`);
        if (!id)
            throw new Error(`Prefab fragment ID is missing (prefab: ${this.url})`);

        let fragment = this._fragments.get(id);
        if (fragment)
            return fragment;

        const data = this._findFragment(id, this.data);
        if (!data)
            throw new Error(`Prefab fragment was not found: ${id} (prefab: ${this.url})`);

        fragment = new PrefabFragment(this, data, id);
        this._copyDependenciesTo(fragment);
        fragment.addReference();
        this._fragments.set(id, fragment);
        return fragment;
    }

    private _findFragment(id: string, data: PrefabNodeData): PrefabNodeData | null {
        if (data._$id === id)
            return data;
        for (const child of data._$child ?? []) {
            const found = this._findFragment(id, child);
            if (found)
                return found;
        }
        return null;
    }

    private _copyDependenciesTo(fragment: PrefabImpl): void {
        const resources = PrefabImpl._validateDependencies(this._dependencySnapshot, this.url, "create");
        fragment._setDependencies(this._dependencySnapshot);
        fragment.addDeps(resources);
    }

    /**
     * @en Create an instance of the prefab.
     * @param options Optional parameters for instance creation.
     * @param errors Array to store any errors encountered during instance creation.
     * @returns The prefab instance.
     * @zh 创建预制体的实例。
     * @param options 创建实例时的可选参数。
     * @param errors 存储实例创建过程中遇到的错误的数组。
     * @returns 预制体实例。
     */
    create(options?: IHierarchyParseOptions, errors?: any[]): Node {
        if (this.destroyed) {
            throw new Error(`Prefab has been destroyed: ${this.url}`);
        }

        PrefabImpl._validateDependencies(this._dependencySnapshot, this.url, "create");

        let runtime = ClassUtils.getRuntime(this.url);
        if (runtime) {
            if (!options)
                options = { runtime };
            else if (!options.runtime)
                options = Object.assign({ runtime }, options);
        }
        options = options || {};
        options.prefab = this;
        let ret = this.api.parse(this.data, options, errors);
        if (Array.isArray(ret)) {
            if (ret.length == 1) {
                ret[0].url = this.url;
            }
            return ret[0];
        }
        else {
            ret.url = this.url;
            return ret;
        }
    }

    protected _disposeResource(): void {
        super._disposeResource();
        for (const fragment of this._fragments.values())
            fragment.removeReference();
        this._fragments.clear();
    }
}

/**
 * @en A reusable node fragment derived from a prefab.
 * @zh 从 Prefab 派生的可复用节点片段。
 */
export class PrefabFragment extends PrefabImpl {
    readonly sourceURL: string;
    readonly fragmentId: string;

    /** @internal */
    constructor(source: PrefabImpl, data: PrefabNodeData, fragmentId: string) {
        super(source.api, data);
        this.sourceURL = source.url ?? "";
        this.fragmentId = fragmentId;
        this.fromDCC = source.fromDCC;
        const suffix = encodeURIComponent(fragmentId);
        this.url = this.sourceURL ? `${this.sourceURL}#${suffix}` : `#${suffix}`;
    }

    override getFragment(id: string | null): PrefabFragment {
        if (id === this.fragmentId) {
            if (this.destroyed)
                throw new Error(`Prefab has been destroyed: ${this.url}`);
            return this;
        }
        return super.getFragment(id);
    }
}
