import { Sprite } from "./Sprite";
import { TransformKind } from "./SpriteConst";
import { MSDFFont } from "./MSDFFont";
import type { MSDFFontGlyph } from "./MSDFFont";
import { ColorUtils } from "../utils/ColorUtils";
import type { Graphics } from "./Graphics";

type GlyphPlacement = {
    glyph: MSDFFontGlyph;
    x: number;
    baseline: number;
};

type MeshData = {
    vertices: number[];
    uvs: number[];
    indices: number[];
    fillColors: number[];
    outlineColors: number[];
    glowColors: number[];
    shadowColors: number[];
    packedParamsA: number[];
    packedParamsB: number[];
};

const EMPTY_COLOR = "#00000000";

function finite(value: number, name: string): number {
    if (!Number.isFinite(value))
        throw new TypeError(`MSDFText ${name} must be finite`);
    return value;
}

function nonNegative(value: number, name: string): number {
    finite(value, name);
    if (value < 0)
        throw new RangeError(`MSDFText ${name} must be non-negative`);
    return value;
}

function unit(value: number, name: string): number {
    finite(value, name);
    if (value < 0 || value > 1)
        throw new RangeError(`MSDFText ${name} must be between 0 and 1`);
    return value;
}

function clampByte(value: number): number {
    return Math.max(0, Math.min(255, Math.round(value * 255)));
}

function appendGlyph(mesh: MeshData, font: MSDFFont, placement: GlyphPlacement, scale: number,
    offsetX: number, offsetY: number, fill: number, outline: number, glow: number, shadow: number,
    packedParamsA: number, packedParamsB: number): void {
    const plane = placement.glyph.planeBounds;
    const x0 = placement.x + plane[0] * scale + offsetX;
    const x1 = placement.x + plane[2] * scale + offsetX;
    const y0 = placement.baseline - plane[3] * scale + offsetY;
    const y1 = placement.baseline - plane[1] * scale + offsetY;
    if (x0 === x1 || y0 === y1)
        return;

    const uv = placement.glyph.uv;
    let v0 = uv[1];
    let v1 = uv[3];
    if (font.yOrigin === "bottom") {
        v0 = 1 - uv[3];
        v1 = 1 - uv[1];
    }

    const base = mesh.vertices.length / 2;
    mesh.vertices.push(x0, y0, x1, y0, x1, y1, x0, y1);
    mesh.uvs.push(uv[0], v0, uv[2], v0, uv[2], v1, uv[0], v1);
    mesh.indices.push(base, base + 1, base + 2, base, base + 2, base + 3);
    for (let i = 0; i < 4; i++) {
        mesh.fillColors.push(fill);
        mesh.outlineColors.push(outline);
        mesh.glowColors.push(glow);
        mesh.shadowColors.push(shadow);
        mesh.packedParamsA.push(packedParamsA);
        mesh.packedParamsB.push(packedParamsB);
    }
}

function createMesh(): MeshData {
    return {
        vertices: [],
        uvs: [],
        indices: [],
        fillColors: [],
        outlineColors: [],
        glowColors: [],
        shadowColors: [],
        packedParamsA: [],
        packedParamsB: [],
    };
}

/**
 * @en A retained MSDF text component. It deliberately does not alter Text or BitmapFont behavior.
 * @zh 保留式 MSDF 文本组件，故意不改变 Text 和 BitmapFont 的既有行为。
 */
export class MSDFText extends Sprite {
    private static _fonts: Record<string, MSDFFont> = Object.create(null);

    private _font: MSDFFont | null = null;
    private _fontName = "";
    private _text = "";
    private _fontSize = 16;
    private _letterSpacing = 0;
    private _lineSpacing = 0;
    private _wordWrap = false;
    private _fillColor = "#ffffffff";
    private _outlineColor = EMPTY_COLOR;
    private _glowColor = EMPTY_COLOR;
    private _shadowColor = EMPTY_COLOR;
    private _msdfEdgeWidth = 1 / 255;
    private _glowStrength = 0;
    private _shadowStrength = 0;
    private _shadowOffsetX = 0;
    private _shadowOffsetY = 0;
    private _layoutWidth = 0;
    private _layoutHeight = 0;
    private _layoutDirty = true;
    private _building = false;
    private _ready = false;

    constructor() {
        super();
        this._ready = true;
    }

    /** Register a named MSDF font with one owner reference. */
    static registerFont(name: string, font: MSDFFont): void {
        if (typeof name !== "string" || name.length === 0)
            throw new TypeError("MSDFText font name must be a non-empty string");
        if (!(font instanceof MSDFFont) || font.destroyed)
            throw new TypeError("MSDFText.registerFont requires a live MSDFFont");
        const old = MSDFText._fonts[name];
        if (old === font)
            return;
        font.addReference();
        MSDFText._fonts[name] = font;
        old?.removeReference();
    }

    /** Remove a named font and optionally destroy it after the registry releases its reference. */
    static unregisterFont(name: string, destroy = true): void {
        const font = MSDFText._fonts[name];
        if (!font)
            return;
        delete MSDFText._fonts[name];
        font.removeReference();
        if (destroy && font.referenceCount === 0)
            font.destroy();
    }

    get font(): MSDFFont | null {
        return this._font;
    }

    set font(value: MSDFFont | null) {
        if (value !== null && (!(value instanceof MSDFFont) || value.destroyed))
            throw new TypeError("MSDFText.font requires a live MSDFFont or null");
        if (value === this._font)
            return;
        if (this.destroyed && value)
            throw new Error("cannot assign an MSDF font to a destroyed MSDFText");
        this.graphics.clear(true);
        value?.addReference();
        const old = this._font;
        this._font = value;
        this._fontName = "";
        old?.removeReference();
        this._invalidateLayout();
    }

    get fontName(): string {
        return this._fontName;
    }

    set fontName(value: string) {
        if (value == null || value === "") {
            this.font = null;
            return;
        }
        if (typeof value !== "string")
            throw new TypeError("MSDFText.fontName must be a string");
        const font = MSDFText._fonts[value];
        if (!font)
            throw new Error(`MSDFText font '${value}' is not registered`);
        this.font = font;
        this._fontName = value;
    }

    get text(): string {
        return this._text;
    }

    set text(value: string) {
        if (typeof value !== "string")
            throw new TypeError("MSDFText.text must be a string");
        if (value === this._text)
            return;
        this._text = value;
        this._invalidateLayout();
    }

    get fontSize(): number {
        return this._fontSize;
    }

    set fontSize(value: number) {
        value = finite(value, "fontSize");
        if (value <= 0)
            throw new RangeError("MSDFText fontSize must be greater than zero");
        if (value !== this._fontSize) {
            this._fontSize = value;
            this._invalidateLayout();
        }
    }

    get letterSpacing(): number {
        return this._letterSpacing;
    }

    set letterSpacing(value: number) {
        value = finite(value, "letterSpacing");
        if (value !== this._letterSpacing) {
            this._letterSpacing = value;
            this._invalidateLayout();
        }
    }

    get lineSpacing(): number {
        return this._lineSpacing;
    }

    set lineSpacing(value: number) {
        value = finite(value, "lineSpacing");
        if (value !== this._lineSpacing) {
            this._lineSpacing = value;
            this._invalidateLayout();
        }
    }

    get wordWrap(): boolean {
        return this._wordWrap;
    }

    set wordWrap(value: boolean) {
        if (typeof value !== "boolean")
            throw new TypeError("MSDFText.wordWrap must be boolean");
        if (value !== this._wordWrap) {
            this._wordWrap = value;
            this._invalidateLayout();
        }
    }

    get color(): string {
        return this._fillColor;
    }

    set color(value: string) {
        if (typeof value !== "string")
            throw new TypeError("MSDFText.color must be a color string");
        if (value !== this._fillColor) {
            this._fillColor = value;
            this._invalidateLayout();
        }
    }

    get outlineColor(): string {
        return this._outlineColor;
    }

    set outlineColor(value: string) {
        this._outlineColor = this._color(value, "outlineColor");
        this._invalidateLayout();
    }

    get glowColor(): string {
        return this._glowColor;
    }

    set glowColor(value: string) {
        this._glowColor = this._color(value, "glowColor");
        this._invalidateLayout();
    }

    get shadowColor(): string {
        return this._shadowColor;
    }

    set shadowColor(value: string) {
        this._shadowColor = this._color(value, "shadowColor");
        this._invalidateLayout();
    }

    get msdfEdgeWidth(): number {
        return this._msdfEdgeWidth;
    }

    set msdfEdgeWidth(value: number) {
        value = unit(value, "msdfEdgeWidth");
        if (value !== this._msdfEdgeWidth) {
            this._msdfEdgeWidth = value;
            this._invalidateLayout();
        }
    }

    get glowStrength(): number {
        return this._glowStrength;
    }

    set glowStrength(value: number) {
        value = unit(value, "glowStrength");
        if (value !== this._glowStrength) {
            this._glowStrength = value;
            this._invalidateLayout();
        }
    }

    get shadowStrength(): number {
        return this._shadowStrength;
    }

    set shadowStrength(value: number) {
        value = unit(value, "shadowStrength");
        if (value !== this._shadowStrength) {
            this._shadowStrength = value;
            this._invalidateLayout();
        }
    }

    get shadowOffsetX(): number {
        return this._shadowOffsetX;
    }

    set shadowOffsetX(value: number) {
        value = finite(value, "shadowOffsetX");
        if (value !== this._shadowOffsetX) {
            this._shadowOffsetX = value;
            this._invalidateLayout();
        }
    }

    get shadowOffsetY(): number {
        return this._shadowOffsetY;
    }

    set shadowOffsetY(value: number) {
        value = finite(value, "shadowOffsetY");
        if (value !== this._shadowOffsetY) {
            this._shadowOffsetY = value;
            this._invalidateLayout();
        }
    }

    get width(): number {
        return super.width;
    }

    set width(value: number) {
        super.width = value;
        this._invalidateLayout();
    }

    protected measureWidth(): number {
        this._ensureLayout();
        return this._layoutWidth;
    }

    protected measureHeight(): number {
        this._ensureLayout();
        return this._layoutHeight;
    }

    protected _transChanged(kind: TransformKind): void {
        super._transChanged(kind);
        if (this._ready && (kind & TransformKind.Width) !== 0)
            this._invalidateLayout();
    }

    destroy(destroyChild = true): void {
        if (this.destroyed)
            return;
        this.graphics.clear(true);
        this.font = null;
        super.destroy(destroyChild);
    }

    private _color(value: string, name: string): string {
        if (typeof value !== "string")
            throw new TypeError(`MSDFText ${name} must be a color string`);
        ColorUtils.create(value);
        return value;
    }

    private _invalidateLayout(): void {
        this._layoutDirty = true;
        if (this._ready && !this._building)
            this._rebuild();
    }

    private _ensureLayout(): void {
        if (this._layoutDirty && !this._building)
            this._rebuild();
    }

    private _rebuild(): void {
        if (this._building)
            return;
        this._building = true;
        this._layoutDirty = false;
        try {
            const graphics = this.graphics;
            graphics.clear(true);
            this._layoutWidth = 0;
            this._layoutHeight = 0;
            if (!this._font || this._font.destroyed || this._text.length === 0)
                return;

            const metrics = this._font.metrics;
            const scale = this._fontSize / metrics.emSize;
            const lineHeight = metrics.lineHeight * scale + this._lineSpacing;
            if (lineHeight <= 0)
                throw new RangeError("MSDFText lineHeight must be greater than zero");
            const ascender = metrics.ascender * scale;
            const widthLimit = this._isWidthSet ? Math.max(0, this._width) : Number.POSITIVE_INFINITY;
            const lines: GlyphPlacement[][] = [];
            const lineWidths: number[] = [];
            let line: GlyphPlacement[] = [];
            let lineWidth = 0;
            let lineY = 0;
            let previousUnicode: number | null = null;

            const flushLine = () => {
                lines.push(line);
                lineWidths.push(lineWidth);
                line = [];
                lineWidth = 0;
                lineY += lineHeight;
                previousUnicode = null;
            };

            for (const character of Array.from(this._text)) {
                if (character === "\n") {
                    flushLine();
                    continue;
                }
                const unicode = character.codePointAt(0)!;
                const glyph = this._font.getGlyph(unicode);
                if (!glyph)
                    throw new Error(`MSDFText font is missing glyph U+${unicode.toString(16).toUpperCase()}`);
                let kerning = previousUnicode == null ? 0 : this._font.getKerning(previousUnicode, unicode);
                let advance = (glyph.advance + kerning) * scale + this._letterSpacing;
                if (this._wordWrap && line.length > 0 && lineWidth + advance > widthLimit) {
                    flushLine();
                    kerning = 0;
                    advance = glyph.advance * scale + this._letterSpacing;
                }
                line.push({ glyph, x: lineWidth, baseline: lineY + ascender });
                lineWidth += advance;
                previousUnicode = unicode;
            }
            if (line.length > 0 || lines.length === 0)
                flushLine();

            for (const width of lineWidths)
                this._layoutWidth = Math.max(this._layoutWidth, width);
            this._layoutHeight = Math.max(0, lines.length * lineHeight - this._lineSpacing);

            const fill = ColorUtils.create(this._fillColor).numColor;
            const outline = ColorUtils.create(this._outlineColor).numColor;
            const glow = ColorUtils.create(this._glowColor).numColor;
            const shadow = ColorUtils.create(this._shadowColor).numColor;
            const edge = clampByte(this._msdfEdgeWidth * this._font.msdf.distanceRange * this._font.msdf.scale);
            const glowStrength = clampByte(this._glowStrength);
            const shadowStrength = clampByte(this._shadowStrength);
            const paramsA = (edge | (glowStrength << 16) | (shadowStrength << 24)) >>> 0;
            const paramsB = (glowStrength | (shadowStrength << 8)) >>> 0;
            const main = createMesh();
            const shadowMesh = createMesh();
            for (const placements of lines) {
                for (const placement of placements) {
                    appendGlyph(main, this._font, placement, scale, 0, 0, fill, outline, glow, 0, paramsA, paramsB);
                    if (shadow !== 0 && shadowStrength > 0)
                        appendGlyph(shadowMesh, this._font, placement, scale, this._shadowOffsetX, this._shadowOffsetY,
                            0, 0, 0, shadow, paramsA, paramsB);
                }
            }
            this._appendMesh(graphics, shadowMesh);
            this._appendMesh(graphics, main);
        }
        finally {
            this._building = false;
        }
    }

    private _appendMesh(graphics: Graphics, mesh: MeshData): void {
        if (mesh.vertices.length === 0)
            return;
        graphics.drawTrianglesMSDF(
            this._font!.atlas,
            0,
            0,
            new Float32Array(mesh.vertices),
            new Float32Array(mesh.uvs),
            new Uint32Array(mesh.indices),
            new Uint32Array(mesh.fillColors),
            new Uint32Array(mesh.outlineColors),
            new Uint32Array(mesh.glowColors),
            new Uint32Array(mesh.shadowColors),
            new Uint32Array(mesh.packedParamsA),
            new Uint32Array(mesh.packedParamsB),
        );
    }
}
